INSERT INTO `activities` (`id`,`excerptEn`,`contentAr`,`excerptAr`,`category`,`images`,`titleEn`,`date`,`titleAr`,`published`,`contentEn`,`featured`) VALUES
('88MxD3Au8wr2rrRTsJMV','A gathering of aviation enthusiasts from various regions in an exciting fly-in event','<p>ملتقى سنوي يجمع هواة ومحترفي الطيران للتعرف على أحدث التقنيات وتبادل الخبرات.</p>','تجمع لعشاق الطيران من مختلف المناطق في فعالية فلاي-ان الممتعة','ملتقى','["https://images.unsplash.com/photo-1559060017-445fb4429b21?q=80&w=800"]','General Aviation Meeting and Fly-In Event in Madinah','2025-01-09','ملتقى الطيران العام وفعالية فلاي-ان بالمدينة المنورة',1,'<p>An annual meeting bringing together aviation hobbyists and professionals to learn about the latest technologies and exchange experiences.</p>',0),
('DdBSYUeAzoeGjW1t2Fjb','The first aviation event in Saudi Arabia combining innovation, culture, and adventure','<p>الحدث الأول للطيران في المملكة العربية السعودية الذي يجمع بين الابتكار والثقافة والمغامرة في عرض استثنائي. هذا أكثر من مجرد عرض جوي، إنه تجمع عالمي حيث يلتقي عشاق الطيران وقادة الصناعة.</p>','الحدث الأول للطيران في المملكة العربية السعودية الذي يجمع بين الابتكار والثقافة والمغامرة','معرض','["https://images.unsplash.com/photo-1540962351504-03099e0a754b?q=80&w=800","https://images.unsplash.com/photo-1436491865332-7a61a109cc05?q=80&w=800"]','General Aviation Airshow Sand and Fun 2025','2025-11-25','معرض الطيران العام ساند اند فن 2025',1,'<p>The first aviation event in Saudi Arabia combining innovation, culture, and adventure in an exceptional display. This is more than just an air show, it is a global gathering where aviation enthusiasts and industry leaders meet.</p>',1),
('Vg1oLWHXbCnvpJr2QpOC','Hosting the FAI General Conference in Riyadh','<p>فخورون باستضافة المؤتمر العام الـ118 للاتحاد الدولي للرياضات الجوية في مدينة الرياض.</p>','استضافة المؤتمر العام للاتحاد الدولي للطيران في الرياض','مؤتمر','["https://images.unsplash.com/photo-1569629743817-70d8db6c323b?q=80&w=800"]','118th FAI General Conference','2024-11-19','المؤتمر العام الـ(118) للاتحاد العالمي للرياضات الجوية',1,'<p>Proud to host the 118th FAI General Conference in Riyadh.</p>',0);
