INSERT INTO `graduates` (`id`,`graduationDate`,`quoteEn`,`storyEn`,`imageUrl`,`quoteAr`,`titleAr`,`nameAr`,`storyAr`,`titleEn`,`featured`,`program`,`nameEn`,`published`) VALUES
('AdNtG7DPdw80Cu22fwhC','2026-02-16','A new milestone in our alumni legacy—proving that every path to the cockpit begins at Fly Wings, where ambition takes flight.','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/graduates%2F1771234608135_%D8%B9%D9%84%D9%8A%20%D8%AE%D8%A8%D8%B1%D8%A7%D9%86%D9%8A.PNG?alt=media&token=3858fc47-b99c-4511-9f71-ee08fe47985a','قصة نجاح جديدة تُضاف إلى سجل خريجينا، تؤكد أن الطريق إلى قمرة القيادة يبدأ من اجنحة الطيران.','خريج','علي خبراني','','Graduate',0,'PPL-IR-CPL','Ali Khabrani',1),
('BXD3lhLPVDgoZ9fL82nu','2026-02-14','A new milestone in our alumni legacy—proving that every path to the cockpit begins at Fly Wings, where ambition takes flight.','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/graduates%2F1771232158120_IMG_6016.PNG?alt=media&token=849d86eb-8772-47d9-80cb-895fbff57c25','قصة نجاح جديدة تُضاف إلى سجل خريجينا، تؤكد أن الطريق إلى قمرة القيادة يبدأ من اجنحة الطيران.','خريج','انور سلامي','','Graduate',0,'PPL-IR-CPL','Anwar Salami',1),
('hvgoQzv2jFxpXltQp82v','2026-07-08','A new success story is added to the record of our graduates, confirming that the path to the cockpit begins with the wings of aviation.','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/graduates%2F1780428962039_%D8%B5%D9%88%D8%B1%D8%A9%20%D8%A7%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85%20%D8%A7%D9%84%D9%82%D8%B1%D9%86%D9%8A.jpeg?alt=media&token=a4c2d0af-241a-4f69-b94f-465166990763','قصة نجاح جديدة تُضاف إلى سجل خريجينا، تؤكد أن الطريق إلى قمرة القيادة يبدأ من اجنحة الطيران.','خريج','مهند باناعمة ','','Graduate',0,'PPL-IR-CPL','Muhannad Banna’ma',1),
('klE6MVL7AV5wuym6KZWf','2025-12-22','A new milestone in our alumni legacy—proving that every path to the cockpit begins at Fly Wings, where ambition takes flight.','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/graduates%2F1768293576579_IMG_4411%20(1).PNG?alt=media&token=901bf5af-d71b-4759-8536-0b4ca19fa096','قصة نجاح جديدة تُضاف إلى سجل خريجينا، تؤكد أن الطريق إلى قمرة القيادة يبدأ من اجنحة الطيران.','خريج','الوليد هزازي','','Graduate',0,'PPL-IR-CPL','Student: Alwaleed Hazazi',1),
('uVwMYZG8e6RpORLWgtYH','2026-01-14','A new milestone in our alumni legacy—proving that every path to the cockpit begins at Fly Wings, where ambition takes flight.','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/graduates%2F1768379254591_IMG_3799.PNG?alt=media&token=6bc7dbec-c04c-4a0e-8ff4-1b57ea620129','قصة نجاح جديدة تُضاف إلى سجل خريجينا، تؤكد أن الطريق إلى قمرة القيادة يبدأ من اجنحة الطيران.','خريج','فيصل الخميسي','','Graduate',0,'PPL-IR-CPL','Faisal Al-Khamisi',1);
INSERT INTO `journey_milestones` (`id`,`descriptionEn`,`titleAr`,`year`,`order`,`descriptionAr`,`titleEn`) VALUES
('4twMdDSKGfLQGHCUELqd','Contributing to achieving Saudi Vision 2030 by qualifying Saudi talents in aviation.','رؤية 2030','2030',4,'المساهمة في تحقيق رؤية المملكة 2030 بتأهيل كوادر سعودية في مجال الطيران.','Vision 2030'),
('CCps4i1B2f3LrvAQpiAu','Expanding services and training programs to cover various aviation fields.','التوسع','2019',2,'ضمن خططنا الاستراتيجية للتوسّع، نفتخر بوجود فرع لأكاديمية أجنحة الطيران في جمهورية جنوب أفريقيا، لتقديم التدريب العملي على الطيران وفق معايير معتمدة وبيئة تدريب احترافية تُمكّن طلابنا من اكتساب الخبرة العملية بكفاءة عالية.\n\nيأتي هذا التوسّع دعمًا لرسالتنا في توفير مسارات تدريب عالمية، تجمع بين الجودة، الاعتماد، وسلاسة الانتقال من الدراسة إلى قمرة القيادة.','Expansion'),
('jlSYLEo55qI8040W2Vjj','Establishing Wings of Aviation as a leading company in aviation training both inside and outside the Kingdom of Saudi Arabia.','التأسيس','2019',1,'تأسيس أجنحة الطيران كشركة رائدة في مجال تدريب الطيران داخل وخارج المملكة العربية السعودية.','Foundation'),
('zXN0Kra1QINAfOfjrJB5','Entering as partners in three aviation academies in the United States','الاعتماد الدولي','2019',3,'الدخول كـ شركاء في ثلاث أكاديميات طيران \nفي الولايات المتحدة الامريكية \n','International Accreditation');
