INSERT INTO `services` (`id`,`descriptionAr`,`titleEn`,`regionalPricing`,`order`,`descriptionEn`,`imageUrl`,`published`,`titleAr`,`terms`) VALUES
('3iKwzsXY6plfInB9qPex','خدمة تأجير طائرات متنوعة للأعضاء المرخصين مع مراعاة جميع المتطلبات التشغيلية','Aircraft Rental','[{"id":"jeddah_1","regionAr":"جدة","regionEn":"Jeddah","price":"15000","currency":"SAR","unit":"hour","notes":"تشمل الطيار والوقود","imageUrl":"https://images.unsplash.com/photo-1540962351504-03099e0a754b?w=800"},{"id":"riyadh_1","regionAr":"الرياض","regionEn":"Riyadh","price":"18000","currency":"SAR","unit":"hour","notes":"تشمل الطيار والوقود والضيافة","imageUrl":"https://images.unsplash.com/photo-1474302770737-173ee21bab63?w=800"},{"id":"makkah_1","regionAr":"مكة المكرمة","regionEn":"Makkah","price":"20000","currency":"SAR","unit":"hour","notes":"خدمة VIP مع مرافق خاص","imageUrl":"https://images.unsplash.com/photo-1436491865332-7a61a109cc05?w=800"},{"id":"jazan_1","regionAr":"جازان","regionEn":"Jazan","price":"22000","currency":"SAR","unit":"hour","notes":"تشمل رحلات ساحلية مميزة","imageUrl":"https://images.unsplash.com/photo-1464037866556-6812c9d1c72e?w=800"}]',4,'Various aircraft rental service for licensed members considering all operational requirements','https://images.unsplash.com/photo-1474302770737-173ee21bab63?q=80&w=800',1,'تأجير الطائرات','[{"textAr":"يجب تقديم الطلب قبل 48 ساعة على الأقل من موعد الرحلة","textEn":"Request must be submitted at least 48 hours before the flight"},{"textAr":"الأسعار لا تشمل الضرائب والرسوم الحكومية","textEn":"Prices do not include taxes and government fees"},{"textAr":"يحق للشركة إلغاء الحجز في حالة الظروف الجوية السيئة","textEn":"The company reserves the right to cancel bookings due to bad weather conditions"},{"textAr":"يتطلب دفع 50% كعربون غير قابل للاسترداد عند الحجز","textEn":"50% non-refundable deposit required upon booking"},{"textAr":"الحد الأقصى للأمتعة 20 كجم لكل راكب","textEn":"Maximum luggage allowance is 20kg per passenger"}]'),
