INSERT INTO `settings` (`id`,`features`,`about`,`stats`,`updatedAt`,`homeAbout`,`home`) VALUES
('pages','{"sectionTitleAr":"لماذا أجنحة الطيران؟","sectionTitleEn":"Why Fly Wings?","sectionSubtitleAr":"نقدم تجربة تدريبية استثنائية ترتكز على الجودة والاحترافية، لنمكّنك من بناء مسار مهني متميز في عالم الطيران.","sectionSubtitleEn":"We offer an exceptional training experience combining quality and professionalism","items":[{"titleEn":"Internationally Certified","id":"1","descriptionEn":"Under the umbrella of the General Authority of Civil Aviation, ICAO","descriptionAr":" ICAO تحت مظلة الهيئة العامة للطيران المدني ","titleAr":"معتمد دوليا"},{"descriptionEn":"An elite group of captains with global experience","descriptionAr":"نخبة من الكباتن ذوي الخبرة العالمية","titleAr":"مدربين محترفين","titleEn":"Professional Instructors","id":"2"},{"id":"3","titleAr":"تدريب دولي","titleEn":"International Training","descriptionAr":"شراكات أكاديميات في الولايات المتحدة الامريكية وفرع معتمد بجنوب أفريقيا","descriptionEn":"Partnerships of academies in the United States of America and an accredited branch in South Africa"},{"titleAr":"برامج مرنة","titleEn":"Flexible Programs","descriptionEn":"Training plans for all levels and needs","id":"4","descriptionAr":"خطط تدريب تناسب جميع المستويات والاحتياجات"}]}','{"heroSubtitleAr":"رواد في مجال تدريب الطيران بالمملكة العربية السعودية، نقدم برامج تدريبية متكاملة تهدف إلى إعداد طيارين محترفين وفق المعايير الدولية، وبإشراف مدربين معتمدين وبيئة تدريب متقدمة.","heroSubtitleEn":"Pioneers of Aviation Training in Saudi Arabia","contentAr":"أجنحة الطيران شركة سعودية رائدة متخصصة في تدريب الطيران، تأسست بهدف تقديم برامج تدريبية احترافية وفق أعلى المعايير المعتمدة، لتأهيل كوادر وطنية قادرة على تلبية متطلبات قطاع الطيران.","contentEn":"Fly Wings is a leading Saudi company specialized in aviation training, established to provide comprehensive training programs.","vision2030Ar":"نساهم في تحقيق رؤية المملكة 2030 من خلال تأهيل كوادر سعودية متخصصة في مجال الطيران، وتطوير صناعة الطيران المحلية، ودعم التحول نحو اقتصاد متنوع ومستدام.","vision2030En":"We contribute to achieving Saudi Arabia\'s Vision 2030 by qualifying specialized Saudi cadres in the aviation field, developing the local aviation industry, and supporting the transformation towards a diverse and sustainable economy.","visionAr":"أن نكون الخيار الأول والرائد في تدريب الطيران بالمملكة العربية السعودية، من خلال تقديم برامج تدريبية معتمدة، وبيئة تعليمية احترافية تُسهم في إعداد كوادر متميزة تلبي متطلبات قطاع الطيران.","visionEn":"To be the first choice for aviation training in the region","missionAr":"تقديم برامج تدريب طيران عالية الجودة تُسهم في تأهيل المتدربين بالمعرفة والمهارات العملية اللازمة للنجاح والتميز في صناعة الطيران، وفق أعلى معايير السلامة والاحترافية.","missionEn":"Providing high-quality training that qualifies trainees for success in aviation","valuesAr":"نلتزم بالجودة والسلامة والاحترافية في جميع ما نقدمه، ونسعى إلى التميز المستمر من خلال تطبيق أعلى المعايير المعتمدة، وتوفير بيئة تدريب احترافية تُعزز الثقة والكفاءة، وتدعم بناء كوادر مؤهلة قادرة على المنافسة والنجاح في قطاع الطيران.","valuesEn":"Quality, safety, professionalism, and excellence in everything we do","imageUrl":"","founderMessageAr":"نؤمن بأن كل حلم بالطيران يستحق أن يتحقق.","founderMessageEn":"We believe that every dream of flying deserves to come true.","founderNameAr":"الكابتن أحمد الشمري","founderNameEn":"Captain Ahmed Al-Shammari","founderTitleAr":"المؤسس والرئيس التنفيذي","founderTitleEn":"Founder & CEO"}','{"graduates":361,"graduatesLabelAr":"خريج ناجح","graduatesLabelEn":"Successful Graduates","years":6,"yearsLabelAr":"سنة خبرة","yearsLabelEn":"Years Experience","partners":3,"partnersLabelAr":"شريك تدريبي","partnersLabelEn":"Training Partners","successRate":85,"successRateLabelAr":"نسبة النجاح","successRateLabelEn":"Success Rate"}','2026-08-27T09:38:49.033Z','{"titleAr":"أجنحة الطيران","titleEn":"Fly Wings","subtitleAr":"في سطور","subtitleEn":"In Brief","descriptionAr":"شركة سعودية رائدة في مجال التدريب على الطيران، تأسست لتكون الخيار الأول للراغبين في تحقيق حلم الطيران.","descriptionEn":"A leading Saudi company in aviation training, established to be the first choice for those who want to achieve their dream of flying.","imageUrl":"https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/pages%2Fhome-about-1768372088478-2%D8%B5%D9%88%D8%B1%D8%A9%20%D8%B7%D9%8A%D8%A7%D8%B1%D8%A9.jpg?alt=media&token=54d5613f-4c73-4ef0-b70d-0c416190f454","statsTitleAr":"الإحصائيات - 2019 - 2025","statsTitleEn":"Statistics - 2019 - 2025","statsItems":[{"value":"58900","labelAr":"ساعات تدريب عملي","id":"1","labelEn":"Practical training hours"},{"value":"19002","labelEn":"Theoretical training hours","id":"2","labelAr":"ساعات تدريب نظري"},{"id":"3","labelEn":"Takeoff and Landing","value":"19934","labelAr":"الإقلاع والهبوط"},{"value":"361","id":"4","labelEn":"Aviation trainee","labelAr":"متدرب طيران"},{"value":"209","id":"1768382611969","labelEn":"They obtained all the licenses","labelAr":"حصلوا على جميع الرخص"},{"labelEn":"They joined the labor market","labelAr":"التحقوا بسوق العمل","id":"1768382666359","value":"101"}],"stat3LabelEn":"Takeoffs & Landings","stat4LabelEn":"Flight Trips","stat1LabelAr":"ساعات تدريب عملي","stat3LabelAr":"ساعات تدريب نظري","stat2LabelAr":"اقلاع وهبوط","stat2LabelEn":"Issued Memberships","stat1Value":"58900","stat4Value":"361","stat2Value":"19934","stat4LabelAr":"متدرب طيران","stat1LabelEn":"Training Hours","stat3Value":"19002"}','{"badgeAr":"","badgeEn":"","heroTitleAr":"","heroTitleEn":"","heroSubtitleAr":"","heroSubtitleEn":"","heroVideoUrl":"https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/videos%2Fhero-1787823472270.mp4?alt=media&token=f9c497b4-e012-44c5-adf7-7fe206f8b902","heroImageUrl":"https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/images%2Fhero-1783346195307.jpeg?alt=media&token=db3bcae8-c320-436c-96e5-404b230a88dd","heroMediaType":"video","heroAnimatedTextAr":"","heroAnimatedTextEn":""}');
INSERT INTO `site_settings` (`id`,`otherSocialLinks`,`metaTitleAr`,`whatsapp`,`addressAr`,`heroImagePackages`,`heroImageContact`,`instagram`,`metaTitleEn`,`heroImageBoardMembers`,`metaDescriptionEn`,`updatedAt`,`twitter`,`showActivitiesSection`,`heroImageJourney`,`linkedin`,`heroImageVision`,`heroImageGallery`,`addressEn`,`showGraduatesSection`,`metaDescriptionAr`,`email`,`heroImageActivities`,`showTrainingProgramsSection`,`tiktok`,`snapchat`,`showPartnersSection`,`heroImageBlog`,`heroImageTrainingTeam`,`showTrainingTeamSection`,`heroImageNews`,`phone`,`heroImageGraduates`,`heroImageFAQ`,`planeImageUrl`,`heroImageAbout`,`youtube`,`facebook`,`pageTitleAr`,`pageSubtitleAr`,`pageSubtitleEn`,`pageTitleEn`,`pages`) VALUES
('general','[]','أجنحة الطيران - للتدريب على الطيران','https://wsend.co/966559254035','المملكة العربية السعودية','','','','Fly Wings - Aviation Training','','The best aviation training programs in Saudi Arabia','2026-02-22T15:09:00.264Z','https://x.com/b_flywings?s=21',0,'','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/hero-images%2F1771772934556_2%D8%B5%D9%88%D8%B1%D8%A9%20%D8%B7%D9%8A%D8%A7%D8%B1%D8%A9.jpg?alt=media&token=39125ecf-d536-43ac-8c3c-471f6f516fd6','','Saudi Arabia',1,'أفضل برامج التدريب على الطيران في المملكة العربية السعودية','info@bflywings.com','',1,'https://www.tiktok.com/@flying.wings1?_r=1&_t=ZS-931x6ZYAUD3','',0,'','',0,'','+966559254035','','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/site-images%2F1768372372098_2%D8%B5%D9%88%D8%B1%D8%A9%20%D8%B7%D9%8A%D8%A7%D8%B1%D8%A9.jpg?alt=media&token=c2c7dd24-838c-4aed-b2dd-55d82a178013','','','',NULL,NULL,NULL,NULL,NULL),
('journey',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'انطلاقة الأكاديمية','شاهد رحلة التحول منذ الانطلاقة 2019م وحتى اليوم','Watch our transformation journey from 2019 to today','Academy Launch',NULL),
('page_seo',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"news":{"descriptionEn":"Stay up to date with the latest Fly Wings news, student achievements, and our participation in educational events and forums.","titleEn":"News | Latest Updates & Events from Fly Wings","descriptionAr":" تابع آخر أخبار أجنحة الطيران، إنجازات طلابنا، مشاركاتنا في الفعاليات والملتقيات التعليمية، وكل جديد في مسيرة الأكاديمية.","titleAr":"الأخبار | آخر أخبار وفعاليات أجنحة الطيران"},"graduates":{"descriptionEn":"Discover the success stories of Fly Wings graduates and how they turned their dream into a real pilot license — start your career path toward the cockpit with confidence.","titleEn":"Graduates | Success Stories from Fly Wings","descriptionAr":" اكتشف قصص نجاح خريجي أجنحة الطيران وكيف حوّلوا حلمهم إلى رخصة طيران واقعية، وابدأ مسارك المهني بثقة نحو قمرة القيادة.","titleAr":"نجوم الطيران | قصص نجاح خريجي أجنحة الطيران"},"faq":{"descriptionEn":"Get clear answers to the most common questions about admission requirements, training duration, costs, and pilot licenses at Fly Wings to help you make the right decision.","titleEn":"FAQ | Everything You Need to Know About Pilot Training","descriptionAr":" إجابات شاملة على أكثر الأسئلة شيوعاً حول شروط الالتحاق، مدة التدريب، التكلفة، والرخص الجوية في أجنحة الطيران، لمساعدتك على اتخاذ القرار الصحيح.","titleAr":"الأسئلة الشائعة | كل ما تريد معرفته عن تدريب الطيران"},"about":{"descriptionEn":"Learn about Fly Wings\' story, vision, and mission in training professional pilots in Saudi Arabia, along with our international accreditations and journey since our founding.","titleEn":"About Us | Fly Wings Vision & Mission in Pilot Training","descriptionAr":"تعرّف على قصة أجنحة الطيران، رؤيتنا ورسالتنا في تأهيل طيارين محترفين بالمملكة العربية السعودية، واعتمادنا الدولي ومسيرتنا منذ التأسيس.","titleAr":"من نحن | رؤية ورسالة أجنحة الطيران للتدريب الجوي"},"blog":{"descriptionEn":"Expert articles on pilot training, PPL, CPL, and IR licenses, training costs, and studying abroad — everything you need to make an informed decision about becoming a pilot.","titleEn":"Fly Wings Blog | Articles & Tips for Aspiring Pilots","descriptionAr":" مقالات متخصصة عن دراسة الطيران، رخص PPL وCPL وIR، تكاليف التدريب، والدراسة في الخارج، لمساعدتك على اتخاذ قرار مدروس نحو احتراف الطيران.","titleAr":"مدونة أجنحة الطيران | مقالات ونصائح عن تدريب الطيارين"},"packages":{"descriptionEn":"Explore Fly Wings\' training packages tailored to your needs, from language preparation to Private and Commercial Pilot Licenses, and choose the package that fits your career goals.","titleEn":"Training Packages | Choose Your Program with Fly Wings","descriptionAr":"استعرض باقات أجنحة الطيران التدريبية المصممة حسب احتياجك، من التأهيل اللغوي إلى رخصة الطيران الخاص والتجاري، واختر الباقة الأنسب لهدفك المهني.","titleAr":"باقات تدريب الطيران | اختر برنامجك مع أجنحة الطيران"},"training-programs":{"descriptionEn":"Discover the stages of your learning journey at Fly Wings: English for Aviation, Ground School, and hands-on flight training, all the way to your PPL and CPL licenses.","titleEn":"Training Programs | From English for Aviation to Pilot License","descriptionAr":"تعرّف على مراحل رحلتك التعليمية في أجنحة الطيران: اللغة الإنجليزية، الدراسات الأرضية، والتدريب العملي على الطيران، وصولاً إلى رخصة PPL وCPL.","titleAr":"البرامج التدريبية | من اللغة الإنجليزية حتى رخصة الطيران"},"home":{"descriptionEn":"Fly Wings is a leading Saudi aviation academy, ICAO and GACA certified, offering complete training programs from English for Aviation to PPL, CPL, and IR licenses. ","titleEn":"Fly Wings | Certified Aviation Training Academy in Saudi Arabia","descriptionAr":"أجنحة الطيران أكاديمية سعودية معتمدة دولياً من ICAO والهيئة العامة للطيران المدني، تقدم برامج متكاملة من اللغة الإنجليزية حتى رخصة PPL وCPL وIR. ابدأ رحلتك نحو قمرة القيادة.","titleAr":"أجنحة الطيران | أكاديمية تدريب طيران معتمدة في السعودية"}}');
INSERT INTO `training_programs` (`id`,`published`,`descriptionEn`,`durationEn`,`shortDescEn`,`imageUrl`,`titleAr`,`shortDescAr`,`titleEn`,`durationAr`,`order`,`descriptionAr`) VALUES
('5sYR5bPqfPTrrO3GJMdD',1,'','','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/training_programs%2F1768737451558_%D8%B7%D9%8A%D8%B1%D8%A7%D9%86%20%D8%B9%D9%85%D9%84%D9%8A.jpg?alt=media&token=444b1339-5d4b-4a8e-9076-09fc31a521a5','الطيران العملي','','Hands-on aviation','',3,'يتعلم المتدرب كيفية اقلاع وهبوط الطائرة والمناورات للالتفاف لليمين واليسار والنزول والصعود والحالات الطارئة في حالة تعطل المحرك ويتم تأهيل الطالب بجميع الحالات الطارئة بشتى انواعها لكي يتفادها أثناء الرحلة حفاظا على الركاب PPL-يتم تعليم الطالب اساسيات الطيران كما هو موضح في التدريب النظري ، الاقلاع والهبوط والمناورات والالتفاف لليمين واليسار  والصعود والنزول والحالات الطارئة ويكون في المرحلة الطيران بالنظر وليس بالعدادات\nIR-وهي تعليم الطالب كيفية الطيران بالعدادات من دون النظر الى الخارج وهذه تنطبق في حالات اذا كانت الرؤية غير واضحة ويتم تعليمه كيفية الطيران ليلاً\nCPL-الطيران على طائرة ذات محركين يتم تدريب الطالب على طائرات ذات محركين نظراً لمتطلبات هيئة الطيران المدني والشركات السعودية ويجب على الطالب اجتياز 25 ساعة على طائرة ذات محركين\n\n'),
('DPY84uUIuaFJ9MQllBPm',1,'','','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/training_programs%2F1768375639981_%D9%85%D8%B9%D9%84%D9%85%20%D8%A7%D9%86%D9%82%D9%84%D8%B4.jpg?alt=media&token=13f95287-cda8-4005-8946-a72c6ef985ab','اللغة الانجليزية','','English language','',1,'برنامج اللغة الانجليزية التحضيري في أكاديمية فلاينج وينجز   \n\nالمستوى الأول: \nيركز برنامج اللغة الإنجليزية في المستوى الاول على تطوير مهارات الاتصال الأساسية في اللغة الإنجليزية اليومية، وعلى بناء  أساس قوي في القواعد والمفردات  مع تطوير مبدئي لمهارة الطلاقة في المحادثة.\n\nالمستوى الثاني: \nيكون التركيز الأساسي في هذه المرحلة على تطوير الاستخدامات اللغوية المتعددة من خلال استخدامات وتعابير مستمدة من اللغة الام. كما يتم التركيز  في هذا المستوى على تحسين وتطوير مهارات النطق و دراسة الصوتيات. \nيهدف هذا المستوى بشكل عام إلى تعزيز جميع المهارات الأربع - القراءة والكتابة والاستماع والتحدث.\n\nالمستوى الثالث: \nيبدا الطلاب في هذه المرحله بتعلم لغة الطيران الإنجليزية التخصصية. \nوذلك من خلال تقنيات متعددة مثل الاستماع إلى تسجيلات تواصل حقيقية بين الطيارين و أبراج المراقبة. وإتقان مصطلحات الطيران في سياقات محاكية للواقع.\n\nبحلول نهاية البرنامج، يكون  لدى الطلاب الثقة والقدرة على التواصل باللغة الإنجليزية بشكل احترافي مما يؤهلهم بجدارة للدراسة والنجاح في عالم الطيران.'),
('MsX4oh8fWvhOB3wOHDRw',1,'','','','https://firebasestorage.googleapis.com/v0/b/flywings-ffe9a.firebasestorage.app/o/training_programs%2F1768737349376_%D9%86%D8%B8%D8%B1%D9%8A.jpg?alt=media&token=b1b13b17-899c-43df-a10b-ae9a5b49c64d','الدراسات الأرضية','','ground school','',2,'يتم تعليم الدراسة الأرضية وتشمل ديناميكية الهواء واجزاء الطائرة ككل ويتم تعليم قوانين الطيران واجزاء المطار ومن ثم حالة الطقس الرياح وسرعتها وكذلك انواع الضباب والعاصفة الرعدية وكيفية تكوينها ومن ثم الحدود الجوية للمدينة التي سيطير بها الطالب تعليماتها بالطول والعرض وارتفاعاتها الخاصة ومن ثم تعليم كيف يخطط الطالب للرحلة ومعها تعليم رموز الطيران الخاصة كالحروف الابجدية ويتم شرح وتفصيل الحالات الطارئة في الطيران اثناء الرحلة\n');
